const raw = $json.request_id ? $json : (($json.body && $json.body.request_id) ? $json.body : $json);

function asArray(value) {
  if (Array.isArray(value)) return value.map(v => String(v).trim()).filter(Boolean);
  if (value === undefined || value === null || value === "") return [];
  return String(value).split(",").map(v => v.trim()).filter(Boolean);
}

function errorResult(code, message) {
  return [{
    json: {
      adapter_status: "error",
      component_id: "ADP-OUTLOOK-SEND",
      component_version: "v1",
      request_id: raw.request_id || null,
      source_component: raw.source_component || null,
      provider: "outlook_m365",
      operation: "send_email",
      validation_status: "invalid",
      message_id: null,
      manual_review_required: true,
      error_code: code,
      error_message: message,
      next_action: "route_to_manual_review_or_error_log",
      status_log_event: "outlook_send_validation_error",
      downstream_components: ["C5-E", "C6-G", "C5-W"],
      source_result: null,
      original_input: raw
    }
  }];
}

if (!raw.request_id) {
  return errorResult("MISSING_REQUEST_ID", "request_id is required.");
}

if (!raw.email || typeof raw.email !== "object") {
  return errorResult("MISSING_EMAIL_OBJECT", "email object is required.");
}

const email = raw.email;

const to = asArray(email.to);
const cc = asArray(email.cc);
const bcc = asArray(email.bcc);

const subject = String(email.subject || "").trim();
const bodyText = String(email.body_text || "");
const bodyHtml = String(email.body_html || "");
const sendFormat = String(email.send_format || "text").trim().toLowerCase();

if (to.length < 1) {
  return errorResult("MISSING_TO", "email.to must contain at least one recipient.");
}

if (!subject) {
  return errorResult("MISSING_SUBJECT", "email.subject is required.");
}

if (!["text", "html"].includes(sendFormat)) {
  return errorResult("INVALID_SEND_FORMAT", "email.send_format must be text or html.");
}

if (sendFormat === "html" && !bodyHtml && !bodyText) {
  return errorResult("MISSING_BODY", "body_html or body_text is required for html email.");
}

if (sendFormat === "text" && !bodyText && !bodyHtml) {
  return errorResult("MISSING_BODY", "body_text or body_html is required for text email.");
}

const message = sendFormat === "html"
  ? (bodyHtml || bodyText)
  : (bodyText || bodyHtml.replace(/<[^>]*>/g, ""));

const outlook = {
  to: to.join(","),
  subject,
  bodyContentType: sendFormat === "html" ? "html" : "text",
  message
};

if (cc.length > 0) {
  outlook.cc = cc.join(",");
}

if (bcc.length > 0) {
  outlook.bcc = bcc.join(",");
}

return [{
  json: {
    adapter_status: "ready",
    component_id: "ADP-OUTLOOK-SEND",
    component_version: "v1",
    request_id: raw.request_id,
    source_component: raw.source_component || null,
    provider: "outlook_m365",
    operation: "send_email",
    validation_status: "valid",
    outlook,
    routing_options: raw.routing_options || {},
    metadata: raw.metadata || {},
    manual_review_required: false,
    error_code: null,
    error_message: null,
    next_action: "execute_outlook_send",
    status_log_event: "outlook_send_request_validated",
    original_input: raw
  }
}];

const validation = $node["Normalize And Validate Outlook Email Request"].json;
const providerResult = $json;
const hasError = Boolean(providerResult.error || providerResult.message?.includes?.("ERROR"));

if (hasError) {
  return [{
    json: {
      adapter_status: "error",
      component_id: "ADP-OUTLOOK-SEND",
      component_version: "v1",
      request_id: validation.request_id || null,
      source_component: validation.source_component || null,
      provider: "outlook_m365",
      operation: "send_email",
      validation_status: validation.validation_status || "valid",
      message_id: null,
      manual_review_required: true,
      error_code: "OUTLOOK_SEND_FAILED",
      error_message: providerResult.error?.message || providerResult.message || "Outlook/M365 send failed.",
      next_action: "route_to_manual_review_or_error_log",
      status_log_event: "outlook_send_failed",
      downstream_components: ["C5-E", "C6-G", "C5-W"],
      source_result: providerResult,
      original_input: validation.original_input || null
    }
  }];
}

return [{
  json: {
    adapter_status: "success",
    component_id: "ADP-OUTLOOK-SEND",
    component_version: "v1",
    request_id: validation.request_id || null,
    source_component: validation.source_component || null,
    provider: "outlook_m365",
    operation: "send_email",
    validation_status: "valid",
    message_id: providerResult.id || providerResult.messageId || null,
    manual_review_required: false,
    error_code: null,
    error_message: null,
    next_action: validation.routing_options?.on_success || "log_status",
    status_log_event: "outlook_send_success",
    downstream_components: ["C5-W"],
    source_result: providerResult,
    original_input: validation.original_input || null
  }
}];
